    jQuery("#discord_chat_username").val(settings.chatUsername || "Streamer (You)");
    jQuery("#discord_chat_avatar_color").val(settings.chatAvatarColor || "#3b82f6");
    jQuery("#discord_chat_reply_count").val(settings.chatReplyCount || 3);
