    applyAvatarColor(settings.chatAvatarColor || "#3b82f6");
    jQuery("#discord_message_order").val(settings.messageOrder || "oldest-first");
    applyFontSize(settings.fontSize || 15);
    updateSourceVisibility();
    updateAllDropdowns();
    if (discordBar) {
      updateApplyLayout();
      updateToggleIcon();
    }
